code='''def transform(grid):
    g = [row[:] for row in grid]
    h, w = len(g), len(g[0])
    objects = []
    # Find solid 3x3 monochrome objects.
    for r in range(h - 2):
        for c in range(w - 2):
            color = g[r][c]
            if color == 0:
                continue
            if all(g[y][x] == color for y in range(r, r + 3) for x in range(c, c + 3)):
                if (r == 0 or c == 0 or g[r-1][c] != color or g[r][c-1] != color):
                    objects.append((r + 1, c + 1, color))
    # Extend each object's center row and column across the grid, filling only empty cells.
    for rr, cc, color in objects:
        for x in range(w):
            if g[rr][x] == 0:
                g[rr][x] = color
        for y in range(h):
            if g[y][cc] == 0:
                g[y][cc] = color
    # Distinct rays leave a blank at each crossing.
    for i, (r, c, col) in enumerate(objects):
        for r2, c2, col2 in objects[i+1:]:
            if col != col2:
                for y, x in ((r, c2), (r2, c)):
                    if g[y][x] == col or g[y][x] == col2:
                        g[y][x] = 0
    return g
'''
